package party.lemons.biomemakeover.client.model;
import net.minecraft.client.model.EntityModel;import net.minecraft.client.model.geom.*;import net.minecraft.client.model.geom.builders.*;import net.minecraft.util.Mth;import party.lemons.biomemakeover.client.render.RootlingRenderState;
public final class RootlingModel extends EntityModel<RootlingRenderState>{
 private final ModelPart body,head,la,ra,ll,rl;
 public RootlingModel(ModelPart root){super(root);body=root.getChild("body");head=root.getChild("head");la=body.getChild("arm_left");ra=body.getChild("arm_right");ll=body.getChild("leg_left");rl=body.getChild("leg_right");}
 public static LayerDefinition createBodyLayer(){MeshDefinition m=new MeshDefinition();PartDefinition r=m.getRoot();PartDefinition b=r.addOrReplaceChild("body",CubeListBuilder.create().texOffs(0,0).addBox(-3.5F,-2.5F,-3.5F,7,5,7).texOffs(0,12).addBox(-2.5F,-3.5F,-2.5F,5,1,5).texOffs(15,12).addBox(-1.5F,2.5F,-1.5F,3,1,3),PartPose.offset(-.5F,18.5F,-.5F));b.addOrReplaceChild("arm_right",CubeListBuilder.create().texOffs(0,18).addBox(-1,0,-1.5F,1,7,3),PartPose.offset(-3.5F,-2.5F,0));b.addOrReplaceChild("arm_left",CubeListBuilder.create().texOffs(8,18).addBox(0,0,-1.5F,1,7,3),PartPose.offset(3.5F,-2.5F,0));b.addOrReplaceChild("leg_right",CubeListBuilder.create().addBox(-.5F,-.5F,-.5F,1,3,1),PartPose.offset(-2,3,0));b.addOrReplaceChild("leg_left",CubeListBuilder.create().texOffs(3,3).addBox(-.5F,-.5F,-.5F,1,3,1),PartPose.offset(2,3,0));PartDefinition h=r.addOrReplaceChild("head",CubeListBuilder.create().texOffs(17,17).addBox(-1.5F,-5,-1.5F,3,5,3).texOffs(21,0).addBox(-4.5F,-6,-1.6F,9,6,0),PartPose.offset(-.5F,15,-.5F));h.addOrReplaceChild("flower1",CubeListBuilder.create().texOffs(16,25).addBox(-5.5F,-6,.1F,8,8,0),PartPose.offsetAndRotation(1,-7,-1,0,.7854F,0));h.addOrReplaceChild("flower2",CubeListBuilder.create().texOffs(16,25).addBox(-4.0607F,-8,.0393F,8,8,0),PartPose.offsetAndRotation(0,-5,0,0,-.7854F,0));return LayerDefinition.create(m,64,64);}
 @Override public void setupAnim(RootlingRenderState s){super.setupAnim(s);head.xRot=s.xRot*(Mth.PI/180);head.yRot=s.yRot*(Mth.PI/180);la.xRot=Mth.cos(s.walkAnimationPos*.6662F)*1.4F*s.walkAnimationSpeed;ra.xRot=-la.xRot;ll.xRot=Mth.cos(s.walkAnimationPos*.6662F)*2*s.walkAnimationSpeed;rl.xRot=-ll.xRot;body.zRot=Mth.sin(s.walkAnimationPos)*.25F*s.walkAnimationSpeed;}
}
